final String NETCONF_ERROR_TAG = "rpc-error";

if (response.getResponse().getContent().contains("<" + NETCONF_ERROR_TAG)
        || response.getResponse().getContent().contains(":" + NETCONF_ERROR_TAG)) {
    throw new DetectedError(response.getCommand(), response.getResponse());
}

if ("1.1".equals(version)) {

    // return immediately, if no MSG_END is found
    if (!response.endsWith("\n##\n")) {
        return false;
    }

    final java.nio.charset.Charset UTF_8 = java.nio.charset.StandardCharsets.UTF_8;
    final byte[] MSG_END       = "\n##\n".getBytes(UTF_8);
    final byte[] responseBytes = response.getBytes(UTF_8);

    int pos = 0;
    while (pos < responseBytes.length) {

        // End-of-message marker: \n##\n
        if (pos + 4 <= responseBytes.length
                && responseBytes[pos] == '\n'
                && responseBytes[pos + 1] == '#'
                && responseBytes[pos + 2] == '#'
                && responseBytes[pos + 3] == '\n') {
            pos += 4;
            break;
        }

        // Chunk header must start with: \n#
        if (pos + 2 > responseBytes.length
                || responseBytes[pos] != '\n'
                || responseBytes[pos + 1] != '#') {
            throw new RuntimeException(
                    "Invalid NETCONF 1.1 chunk header at byte offset " + pos);
        }

        pos += 2;

        // Read decimal chunk size until terminating '\n'
        int sizeStart = pos;
        while (pos < responseBytes.length && responseBytes[pos] != '\n') {
            if (responseBytes[pos] < '0' || responseBytes[pos] > '9') {
                throw new RuntimeException(
                        "Invalid chunk size at byte offset " + pos);
            }
            pos++;
        }

        if (pos >= responseBytes.length) {
            throw new RuntimeException(
                    "Unexpected end of data while reading chunk size");
        }

        int chunkSize = Integer.parseInt(
                new String(
                        responseBytes,
                        sizeStart,
                        pos - sizeStart,
                        java.nio.charset.StandardCharsets.US_ASCII));

        // Prevent malformed frames from causing endless parsing loops
        if (chunkSize <= 0) {
            throw new RuntimeException(
                    "Invalid NETCONF 1.1 chunk size "
                            + chunkSize
                            + " at byte offset "
                            + sizeStart);
        }

        // Skip terminating '\n' after chunk size
        pos++;

        if (pos + chunkSize > responseBytes.length) {
            throw new RuntimeException(
                    "Chunk exceeds available data: size="
                            + chunkSize
                            + ", offset="
                            + pos);
        }

        // Advance by octets, not characters
        pos += chunkSize;
    }

    return pos == responseBytes.length;
} else {
    String text = response.trim();
    return text.endsWith("]]>]]>");
}

List<? extends Command> commands = super.partitionCommands(document);

if ("1.1".equals(version)) {
    for (Command c : commands) {
        int byteLength = c.getContent()
                .getBytes(java.nio.charset.StandardCharsets.UTF_8)
                .length;

        c.setContent("\n#" + byteLength + "\n" + c.getContent());
    }

    Command lastCommand = commands.get(commands.size() - 1);
    lastCommand.setContent(lastCommand.getContent() + "\n##\n");
} else {
    for (Command c : commands) {
        c.setContent(c.getContent() + "]]>]]>");
    }
}

return commands;

if ("1.1".equals(version)) {
    byte[] data = response.getResponse().getContent()
            .getBytes(java.nio.charset.StandardCharsets.UTF_8);

    java.io.ByteArrayOutputStream payload = new java.io.ByteArrayOutputStream();

    int pos = 0;

    while (pos < data.length) {

        // End-of-message marker: \n##\n
        if (pos + 4 <= data.length
                && data[pos] == '\n'
                && data[pos + 1] == '#'
                && data[pos + 2] == '#'
                && data[pos + 3] == '\n') {
            pos += 4;
            break;
        }

        // Chunk header must start with: \n#
        if (pos + 2 > data.length
                || data[pos] != '\n'
                || data[pos + 1] != '#') {
            throw new RuntimeException(
                    "Invalid NETCONF 1.1 chunk header at byte offset " + pos);
        }

        pos += 2;

        // Read decimal chunk size until terminating '\n'
        int sizeStart = pos;
        while (pos < data.length && data[pos] != '\n') {
            if (data[pos] < '0' || data[pos] > '9') {
                throw new RuntimeException(
                        "Invalid chunk size at byte offset " + pos);
            }
            pos++;
        }

        if (pos >= data.length) {
            throw new RuntimeException(
                    "Unexpected end of data while reading chunk size");
        }

        int chunkSize = Integer.parseInt(
                new String(
                        data,
                        sizeStart,
                        pos - sizeStart,
                        java.nio.charset.StandardCharsets.US_ASCII));

        // Prevent malformed frames from causing endless parsing loops
        if (chunkSize <= 0) {
            throw new RuntimeException(
                    "Invalid NETCONF 1.1 chunk size "
                            + chunkSize
                            + " at byte offset "
                            + sizeStart);
        }

        // Skip terminating '\n' after chunk size
        pos++;

        if (pos + chunkSize > data.length) {
            throw new RuntimeException(
                    "Chunk exceeds available data: size="
                            + chunkSize
                            + ", offset="
                            + pos);
        }

        payload.write(data, pos, chunkSize);

        // Advance by octets, not characters
        pos += chunkSize;
    }

    response.getResponse().setContent(
            payload.toString(java.nio.charset.StandardCharsets.UTF_8));
} else {
    String trimmedResponse = response.getResponse().getContent().trim();
    if (trimmedResponse.endsWith("]]>]]>")) {
        response.getResponse().setContent(
                trimmedResponse.substring(
                        0,
                        trimmedResponse.length() - "]]>]]>".length()));
    }
}

return response;
